//! Testnet-only Hyperliquid L1 action signer and order client.
//!
//! Three actions: place a limit order ([`Tif::Alo`], [`Tif::Gtc`], [`Tif::Ioc`]),
//! cancel by order id, and `scheduleCancel` (the dead man's switch). Signing
//! reproduces the official Python SDK byte for byte (msgpack, `connectionId`,
//! r/s/v and the request body), checked against golden vectors generated by
//! `scripts/gen_hl_order_golden.py`. See `docs/ORDER_CLIENT.md`.
//!
//! **Testnet only.** [`Network`] has a single variant, so this crate cannot sign
//! for or address mainnet. No transport ships here: [`ExchangeClient`] takes any
//! [`Transport`], and the tests use a fake one, so nothing is sent on the wire.
//!
//! ```
//! use hl_order::{Action, Decimal8, LimitOrder, Network, Signer, Tif};
//!
//! // The throwaway public test key used by the goldens. Never a real key.
//! let mut key = [0u8; 32];
//! for (i, b) in key.iter_mut().enumerate() {
//!     *b = [0x01, 0x23, 0x45, 0x67, 0x89][i % 5];
//! }
//! let signer = Signer::from_bytes(&key)?;
//! let order = Action::Order(LimitOrder {
//!     asset: 0,
//!     is_buy: true,
//!     px: Decimal8::parse("30000")?.round_px_perp(5)?,
//!     sz: Decimal8::parse("0.0012345")?.floor_to_lot(5)?,
//!     reduce_only: false,
//!     tif: Tif::Alo,
//!     cloid: None,
//! });
//! let signed = signer.sign_l1(Network::Testnet, &order, 1_700_000_000_001, None, None)?;
//! assert_eq!(signed.signature.v, 28);
//! # Ok::<(), Box<dyn std::error::Error>>(())
//! ```

mod action;
mod client;
mod decimal;
mod hex;
mod network;
mod signing;

